{
  "mcpServers": {
    "archlang": {
      "description": "ArchLang remote MCP server (streamable HTTP, no account or API key). Floor plans as code: the AI writes a plain-text .arch file and the compiler draws a dimensioned plan (SVG, DXF, PDF) and reports what is wrong, with machine-applicable fixes. Tools include compile, describe, lint, validate, fix, finish, suggest, complete, explain and link. The plan source you send is compiled on the server; nothing on your machine is read. Open source, MIT. Docs: https://archlang.uk/mcp",
      "type": "http",
      "url": "https://mcp.archlang.uk/mcp"
    }
  }
}
